local MER, W, WF, F, E, I, V, P, G, L = unpack(ElvUI_MerathilisUI)
local module = MER:GetModule("MER_Profiles") ---@class Profiles
local Splash = MER:GetModule("MER_SplashScreen") ---@class SplashScreen

local _G = _G

function module:LoadSkironCooldownManagerProfile()
	local SCMAPI = _G.SCMAPI

	local Profile = (
		E.Forever
		and [[!SCM:1:0!]]
	)
		or [[!SCM:1:0!]]

	local name = I.ProfileNames.Default
	SCMAPI.ImportProfile(name, Profile)
end

function module:ApplySkironCooldownManagerProfile()
	if not E:IsAddOnEnabled("SkironCooldownManager") then
		F.Developer.LogWarning("SkironCooldownManager is not enabled. Will not apply profile.")
		return
	end

	Splash:Wrap("Applying SkironCooldownManager Profile ...", function()
		self:LoadSkironCooldownManagerProfile()

		E:UpdateMedia()
		E:UpdateFontTemplates()

		-- execute elvui update, callback later
		self:ExecuteElvUIUpdate(function()
			Splash:Hide()

			F.Event.TriggerEvent("MER.DatabaseUpdate")
		end, true)
	end, true, "SkironCooldownManager")
end
